package connect

import (
	"errors"
	"fmt"
)

// ResultOf computes the winner of a game of Hex / Polygon.
//
// The board is given as a set of rows, each a string of cells where '.' is an
// empty cell and 'X' or 'O' is a stone. The rows are laid out as a parallelogram
// (each row is visually offset by one cell) but form a regular rectangular grid
// once the spaces are removed.
//
// Player "O" plays from top to bottom and player "X" plays from left to right.
// A player wins when their stones form a connected path between the two sides
// assigned to them. The winning player is returned as a string; an empty string
// means nobody has won yet.
func ResultOf(lines []string) (string, error) {
	if len(lines) == 0 {
		return "", nil
	}

	rows := len(lines)
	cols := len(lines[0])

	// Validate the board: every row must have the same length and only contain
	// the allowed cell values.
	for r, line := range lines {
		if len(line) != cols {
			return "", fmt.Errorf("row %d has %d cells, expected %d", r, len(line), cols)
		}
		for _, c := range line {
			if c != '.' && c != 'X' && c != 'O' {
				return "", fmt.Errorf("invalid cell %q", c)
			}
		}
	}

	oWins := connects(lines, 'O',
		func(r, c int) bool { return r == 0 },        // top edge
		func(r, c int) bool { return r == rows-1 })   // bottom edge
	xWins := connects(lines, 'X',
		func(r, c int) bool { return c == 0 },        // left edge
		func(r, c int) bool { return c == cols-1 })   // right edge

	switch {
	case oWins && xWins:
		// A valid Hex board can never have both players connect at once.
		return "", errors.New("both players cannot win")
	case oWins:
		return "O", nil
	case xWins:
		return "X", nil
	default:
		return "", nil
	}
}

// connects reports whether the stones of the given player form a connected path
// from any cell satisfying start to any cell satisfying goal.
func connects(lines []string, player rune, start, goal func(r, c int) bool) bool {
	rows := len(lines)
	cols := len(lines[0])

	seen := make([][]bool, rows)
	for r := range seen {
		seen[r] = make([]bool, cols)
	}

	queue := make([][2]int, 0, rows*cols)
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if lines[r][c] == player && start(r, c) {
				seen[r][c] = true
				queue = append(queue, [2]int{r, c})
			}
		}
	}

	for head := 0; head < len(queue); head++ {
		r, c := queue[head][0], queue[head][1]
		if goal(r, c) {
			return true
		}
		for _, n := range neighbors(r, c) {
			nr, nc := n[0], n[1]
			if nr < 0 || nr >= rows || nc < 0 || nc >= cols {
				continue
			}
			if seen[nr][nc] || lines[nr][nc] != player {
				continue
			}
			seen[nr][nc] = true
			queue = append(queue, [2]int{nr, nc})
		}
	}
	return false
}

// neighbors returns the six hexagonal neighbours of cell (r, c). Because each
// row is offset by one cell, the cells in the row above sit at columns c and
// c+1 while the cells in the row below sit at columns c-1 and c.
func neighbors(r, c int) [][2]int {
	return [][2]int{
		{r, c - 1},
		{r, c + 1},
		{r - 1, c},
		{r - 1, c + 1},
		{r + 1, c - 1},
		{r + 1, c},
	}
}

